@Component @Order(1)
public class AuthenticationFilter implements Filter {
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest httpRequest = (HttpServletRequest) req;
        HttpServletResponse httpResponse = (HttpServletResponse) res;
        String token = httpRequest.getHeader("token");
        String apiKey = httpRequest.getHeader("x-api-key");
        if (token == null || !token.equals("12345")) {
            httpResponse.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }
        if (apiKey == null || !apiKey.equals("secret123")) {
            httpResponse.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            httpResponse.setContentType("application/json");
            httpResponse.getWriter().write("{ \"message\" : \"Invalid or missing Api key\" }");
            return;
        }
        chain.doFilter(req, res);
    }
}

// LoggingFilter is @Order(2): sets X-Request-ID, prints "Incoming Request : ...",
// then chain.doFilter in try, and prints status + time in finally.

// LoggingFilter (@Order(2))
long startTime = System.currentTimeMillis();
httpResponse.setHeader("X-Request-ID", UUID.randomUUID().toString());
System.out.println("Incoming Request : " + httpRequest.getMethod() + " " + httpRequest.getRequestURI());
try {
    filterChain.doFilter(servletRequest, servletResponse);
} finally {
    long duration = System.currentTimeMillis() - startTime;
    System.out.println("Response status: " + httpResponse.getStatus());
    System.out.println("API Response time : " + duration);
}

